# Helpers for docs/control-panel-entry-sheet.md.
#
# Prose is kept in line arrays rather than here-strings: a here-string's line
# endings follow the checkout, and the generated file must not.

# --- rows -------------------------------------------------------------------

# What a button is programmed as. Two buttons with the same key are programmed
# identically, which is how inherited rows are found.
function Get-SheetButtonKey {
    [CmdletBinding()]
    [OutputType([string])]
    param([Parameter(Mandatory)]$Button)
    if ($Button.Relay) { return "relay|$($Button.Relay)" }
    return "native|$($Button.Native)|$($Button.Hold)"
}

function Get-SheetProgram {
    [CmdletBinding()]
    [OutputType([string])]
    param([Parameter(Mandatory)]$Model, [Parameter(Mandatory)]$Button)
    if ($Button.Relay) {
        return "Keyboard: ``$($Model.ChordsById[$Button.Relay].Display)``"
    }
    if ($Button.Hold) { return "$($Button.Native) (held)" }
    return $Button.Native
}

function Get-SheetAutoRelease {
    [CmdletBinding()]
    [OutputType([string])]
    param([Parameter(Mandatory)]$Model, [Parameter(Mandatory)]$Button)
    if ($Button.Relay) {
        if ($Model.Actions[$Button.Relay].Kind -eq 'layer') { return '**Off**' } else { return 'On' }
    }
    if ($Button.Hold) { return '**Off**' }
    if ($Button.Native -like 'Keyboard:*') { return 'On' }
    return '-'
}

function Get-SheetResult {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory)]$Model,
        [Parameter(Mandatory)]$Button,
        [Parameter(Mandatory)][string]$ButtonId
    )
    if ($Button.Relay) {
        $action = $Model.Actions[$Button.Relay]
        if ($action.Kind -eq 'layer') { return "$($action.Label); see the scroll layers below" }
        $text = $action.Label
    } else {
        $text = $Button.Label
    }
    if ($ButtonId -like '*TriggerPush') { $text += '; scroll layer unassigned' }
    return $text
}

# --- sections, in order; each ends with a blank line ------------------------

function Get-SheetIntro {
    [CmdletBinding()]
    [OutputType([string[]])]
    param([Parameter(Mandatory)]$Model)

    $lines = @(
        '# Swiftpoint Control Panel entry sheet'
        ''
        '<!-- Generated by tools/generate.ps1 from config/bindings.json. Do not edit. -->'
        ''
        "Chord set ``$($Model.ActiveChordSet)``. A button marked **Keyboard: F..** emits that one key and nothing"
        'else; the relay resolves it. Every other button is programmed natively and never reaches the'
        'relay. Each relay key is unique across all profiles, so the relay does not need to know which'
        'profile is active.'
        ''
        '## Profiles'
        ''
        '| Profile | Control Panel profile | Linked app |'
        '|---|---|---|'
    )
    foreach ($entry in $Model.Profiles) {
        if ($entry.App) {
            $app = "``$($entry.App)``"
        } elseif ($entry.AppHint) {
            $app = "$($entry.AppHint) (your choice)"
        } else {
            $app = 'none: active wherever no sub-profile is'
        }
        $lines += "| $($entry.Label) | $($entry.ControlPanel) | $app |"
    }
    return [string[]]($lines + '')
}

# One table per profile. In a sub-profile, a button programmed exactly as in
# Global Default is marked inherited and left alone.
function Get-SheetProfileSection {
    [CmdletBinding()]
    [OutputType([string[]])]
    param([Parameter(Mandatory)]$Model)

    $default = $Model.GlobalDefault
    $lines = @()
    foreach ($entry in $Model.Profiles) {
        $lines += "## $($entry.Label)"
        $lines += ''
        if (-not $entry.IsGlobalDefault) {
            $lines += "Sub-profile. A row marked *inherited* matches $($default.Label) and is left alone."
            $lines += ''
        }
        $lines += '| Button | Program in Control Panel | Auto-Release Outputs | Result |'
        $lines += '|---|---|---|---|'
        foreach ($physical in $script:PhysicalButtons) {
            $button = $entry.Buttons[$physical.Id]
            $result = Get-SheetResult -Model $Model -Button $button -ButtonId $physical.Id
            $sameAsDefault = (Get-SheetButtonKey -Button $button) -eq (Get-SheetButtonKey -Button $default.Buttons[$physical.Id])
            if (-not $entry.IsGlobalDefault -and $sameAsDefault) {
                $lines += "| $($physical.Label) | *inherited* | | $result |"
            } else {
                $program = Get-SheetProgram -Model $Model -Button $button
                $autoRelease = Get-SheetAutoRelease -Model $Model -Button $button
                $lines += "| $($physical.Label) | $program | $autoRelease | $result |"
            }
        }
        $lines += ''
    }
    return [string[]]$lines
}

function Get-SheetLayerSection {
    [CmdletBinding()]
    [OutputType([string[]])]
    param([Parameter(Mandatory)]$Model)

    $layers = @($Model.Chords | Where-Object { $_.Kind -eq 'layer' })
    if ($layers.Count -eq 0) { return [string[]]@() }

    $lines = @(
        '## Scroll layers'
        ''
        'While the trigger is held the wheel no longer scrolls: each direction opens its link at most'
        'once per hold, and releasing the trigger produces no output. To repeat a direction, release'
        'and push again.'
        ''
        '| Trigger held | Scroll left | Scroll right | Scroll forward | Scroll back |'
        '|---|---|---|---|---|'
    )
    foreach ($chord in $layers) {
        $layer = $Model.Actions[$chord.Id].Layer
        $cells = foreach ($direction in $script:Directions) {
            if ($layer[$direction]) { $Model.Actions[$layer[$direction]].Label } else { 'unassigned' }
        }
        $lines += "| $($chord.Where) (``$($chord.Display)``) | $($cells -join ' | ') |"
    }
    return [string[]]($lines + '')
}

function Get-SheetStepSection {
    [CmdletBinding()]
    [OutputType([string[]])]
    param([Parameter(Mandatory)]$Model)

    return [string[]]@(
        '## Steps'
        ''
        '1. Control Panel, then **Expert Mode** (bottom left).'
        "2. Select **Global Default** and program it from the **$($Model.GlobalDefault.Label)** table."
        '3. For each sub-profile: create it, link it to the app in the Profiles table, then program'
        '   every row not marked *inherited*.'
        '4. To program a button:'
        '   1. Click the button on the mouse diagram.'
        '   2. **+ Add mappings**, if it has none.'
        '   3. Click the output name (reads **Do Nothing**).'
        '   4. **Output Type**, then a keyboard or mouse output.'
        '   5. Enter the output. The keyboard recorder cannot capture F13-F24 (no physical key), so'
        '      pick them from the key list.'
        '   6. Set **Auto-Release Outputs** as the table says.'
        '5. Confirm the mappings are in onboard flash (automatic in Control Panel 3.1.1.0+).'
        ''
        '## Held outputs'
        ''
        'A row with Auto-Release **Off** must press its output on **Press** and release it on'
        '**Release**. A held game key (sneak, sprint) depends on this, and so does a scroll layer:'
        'the relay leaves the layer only when the key goes up. With Auto-Release on, a layer trigger'
        'reads as an instant press and release, and the wheel keeps scrolling the page.'
        ''
    )
}

function Get-SheetTurnSection {
    [CmdletBinding()]
    [OutputType([string[]])]
    param([Parameter(Mandatory)]$Model)

    if (@($Model.Chords | Where-Object { $_.Kind -eq 'turn' }).Count -eq 0) { return [string[]]@() }
    return [string[]]@(
        '## Calibrating the 180 degree turn'
        ''
        "The turn moves the mouse by ``turn.counts`` = $($Model.Turn.Counts) relative counts. The angle"
        'depends on the in-game sensitivity; recalibrate after changing it.'
        ''
        '1. Minecraft, **Options > Controls > Mouse Settings**: **Raw Input** on.'
        '2. Press **F3** and note the yaw in the **Facing** line.'
        '3. Press the turn button, and note the new yaw. Let *d* be the angle turned, in 0..360.'
        '4. Set `turn.counts` to round(counts * 180 / *d*), run `tools/generate.ps1`, then'
        '   tray icon > **Reload**.'
        ''
    )
}

function Get-SheetLinkSection {
    [CmdletBinding()]
    [OutputType([string[]])]
    param()

    return [string[]]@(
        '## Contest links'
        ''
        '`config/bindings.json` holds placeholders only, since the repository is public. The real'
        'URLs go in `config/links.local.json`, which is gitignored:'
        ''
        '1. Copy `config/links.local.example.json` to `config/links.local.json`.'
        '2. Replace each placeholder. A key left out falls back to its placeholder, and the relay'
        '   logs a warning once.'
        '3. Optionally set `browser` to the full path of the browser linked to Contest Management.'
        '   A link opened in a different browser moves focus there and switches the profile off.'
        ''
        'The relay re-reads the file on its next use; no reload is needed.'
        ''
    )
}

function Get-SheetTroubleshootingSection {
    [CmdletBinding()]
    [OutputType([string[]])]
    param()

    return [string[]]@(
        '## If a button does nothing'
        ''
        'Run `pwsh -File tools/verify.ps1 -Test` and watch for a tooltip.'
        ''
        '- **The selftest passes but the mouse shows no tooltip**: the Control Panel is not emitting'
        '  the key. If F13-F24 are not offered in its key list, set `activeChordSet` to'
        '  `"ctrlAltShift"` in `config/bindings.json`, re-run `tools/generate.ps1`, reload the relay'
        '  (tray icon > **Reload**), and reprogram. The relay reads its bindings only when it starts.'
        '- **The page scrolls while a layer trigger is held**: Auto-Release Outputs is on for that'
        '  trigger. Turn it off.'
        '- **A contest button opens a placeholder** (a `.example` page, or a Discord link with'
        '  `_ID` in it): its key is missing from `config/links.local.json`, or still holds the value'
        '  copied from the example.'
        '- **A native button acts in the wrong profile**: the sub-profile is not linked to the'
        '  focused app. Check the exe name in Task Manager, Details tab.'
        ''
    )
}
